window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-38901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνήκω</h1><div class=\"entry-meta\"><span>DGP · ordem 2751 na letra σ · nº geral 38901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar reunido; reunir-se: σ. εἰς ἕν xen. reunir-se em um todo 2 convergir em; terminar em, εἰς e ac.: σ. εἰς ὀξύ artt. terminar em ponta. 〈σύν, ἥκω〉</p></section></article>\n<article id=\"entry-dgp-38902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηλικιώτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2752 na letra σ · nº geral 38902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = ἡλικιώτης.</p></section></article>\n<article id=\"entry-dgp-38903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνῆλιξ,</h1><div class=\"entry-meta\"><span>DGP · ordem 2753 na letra σ · nº geral 38903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνῆλιξ, ικος (masc., fem., n.) 1 da mesma idade; contemporâneo ♦ ὁ συνῆλιξ 2 companheiro de alguém, dat. 〈σύν, ἧλιξ〉</p></section></article>\n<article id=\"entry-dgp-38904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνημερεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2754 na letra σ · nº geral 38904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">passar o dia junto; viver com alguém, dat. ou μετά e gen. 〈σύν, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-38905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνημοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2755 na letra σ · nº geral 38905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acordo; convenção 2 pl. laços de amizade. 〈συνίημι〉</p></section></article>\n<article id=\"entry-dgp-38906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηόρος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2756 na letra σ · nº geral 38906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνάορος, ος, ον 1 associado a; harmonizado com, dat. 2 unido a, dat. ♦ ὁ e ἡ συνηόρος 3 esposo, esposa. 〈συναείρω〉</p></section></article>\n<article id=\"entry-dgp-38907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηρεμόω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2757 na letra σ · nº geral 38907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνηρεμόω-ῶ alqueivar (a terra).</p></section></article>\n<article id=\"entry-dgp-38908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηρετέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2758 na letra σ · nº geral 38908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνηρετέω-ῶ 1 duv. prestar serviço junto; ajudar 2 adaptar-se a, dat.</p></section></article>\n<article id=\"entry-dgp-38909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηρετμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2759 na letra σ · nº geral 38909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">remar junto com, dat. 〈σύν, ἐρετμός〉</p></section></article>\n<article id=\"entry-dgp-38910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηρεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2760 na letra σ · nº geral 38910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coberto de, dat. 2 coberto; oculto 3 que recobre. 〈συν, ἐρέφω〉</p></section></article>\n<article id=\"entry-dgp-38911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνῆρσα</h1><div class=\"entry-meta\"><span>DGP · ordem 2761 na letra σ · nº geral 38911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de συναραρίσκω.</p></section></article>\n<article id=\"entry-dgp-38912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνῆτε</h1><div class=\"entry-meta\"><span>DGP · ordem 2762 na letra σ · nº geral 38912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª pl. impf. de σύνειμι ou subj. aor.2 de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηττάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2763 na letra σ · nº geral 38913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sofrer derrota junto.</p></section></article>\n<article id=\"entry-dgp-38914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνηχέω</h1><div class=\"entry-meta\"><span>DGP · ordem 2764 na letra σ · nº geral 38914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 ressoar junto ou em uníssono 2 produzir um som igual; fazer eco a, dat.</p></section></article>\n<article id=\"entry-dgp-38915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνήχησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2765 na letra σ · nº geral 38915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">consonância; acordo. 〈συνηχέω〉</p></section></article>\n<article id=\"entry-dgp-38916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνήωρ</h1><div class=\"entry-meta\"><span>DGP · ordem 2766 na letra σ · nº geral 38916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">συνήορος.</p></section></article>\n<article id=\"entry-dgp-38917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνθακος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2767 na letra σ · nº geral 38917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξύνθακος, ος, ον que se senta com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθάλπω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2768 na letra σ · nº geral 38918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνθάλπω 1 aquecer junto ou completamente 2 consolar; reconfortar.</p></section></article>\n<article id=\"entry-dgp-38919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 2769 na letra σ · nº geral 38919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enterrar uma pessoa, ac. com outra ou com algo, dat. 2 ajudar uma pessoa, dat., a sepultar outra, ac.</p></section></article>\n<article id=\"entry-dgp-38920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθεάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2770 na letra σ · nº geral 38920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser espectador junto com outrem 2 examinar junto ou ao mesmo tempo 3 perceber num golpe de vista.</p></section></article>\n<article id=\"entry-dgp-38921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθέλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2771 na letra σ · nº geral 38921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">συνεθέλω.</p></section></article>\n<article id=\"entry-dgp-38922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνθεο</h1><div class=\"entry-meta\"><span>DGP · ordem 2772 na letra σ · nº geral 38922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. aor.2 méd. poét. de συντίθημι.</p></section></article>\n<article id=\"entry-dgp-38923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθεσία,</h1><div class=\"entry-meta\"><span>DGP · ordem 2773 na letra σ · nº geral 38923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. συνθεσίη, ης (ἡ) 1 convenção; acordo; pacto 2 instruções; ordens. 〈συντίθημι〉</p></section></article>\n<article id=\"entry-dgp-38924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνθεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2774 na letra σ · nº geral 38924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de pôr junto; arranjo; combinação; composição 2 Ret. e Gram. composição de letras, de palavras, de frases 3 composição; obra; peça oratória, literária, poética ou musical 4 Medic. combinação; mistura 5 Matem. adição 6 Lóg. síntese 7 acordo; pacto; convenção. 〈συντίθημι〉</p></section></article>\n<article id=\"entry-dgp-38925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2775 na letra σ · nº geral 38925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que compõe; que combina 2 hábil em compor, em dispor bem, gen. ♦ ἡ συνθετική 3 arte da composição. 〈σύνθετος〉</p></section></article>\n<article id=\"entry-dgp-38926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνθετο</h1><div class=\"entry-meta\"><span>DGP · ordem 2776 na letra σ · nº geral 38926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. συντίθημι.</p></section></article>\n<article id=\"entry-dgp-38927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνθετος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2777 na letra σ · nº geral 38927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e ant. át. ξύνθετος, ος, ον 1 formado de partes unidas; composto 2 complexo 3 composto; inventado; fictício 4 convencionado; pactuado: ἐκ συνθέτου her. segundo o que foi convencionado ♦ τὸ σύνθετον 5 o composto 6 pl., Medic. excrementos sólidos. 〈συντίθημι〉</p></section></article>\n<article id=\"entry-dgp-38928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθέω</h1><div class=\"entry-meta\"><span>DGP · ordem 2778 na letra σ · nº geral 38928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συνθεύσομαι) 1 correr com, dat. 2 convergir 3 topar com 4 estar ou ficar de acordo com, dat. 5 Medic. (músculo) contrair-se.</p></section></article>\n<article id=\"entry-dgp-38929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθήγω</h1><div class=\"entry-meta\"><span>DGP · ordem 2779 na letra σ · nº geral 38929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aguçar, excitar fortemente.</p></section></article>\n<article id=\"entry-dgp-38930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθήκη,</h1><div class=\"entry-meta\"><span>DGP · ordem 2780 na letra σ · nº geral 38930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνθήκη, ης (ἡ) 1 convenção; pacto; acordo: συνθήκῃ ou ἐκ διὰ συνθήκης ou κατὰ συνθήκην por convenção, συνθήκας σφίσι αὐτοῖσι τοὺς Ἴωνας ἠνάγκασε ποιέεσθαι her. obrigou os jônios a concluir um acordo entre eles, συνθήκας ἀναιρεῖν ou λύειν ou παραβαίνειν violar um acordo 2 pacto escrito; tratado 3 artigo de um tratado 4 combinação de elementos no discurso 5 crist., pl. votos monásticos. 〈συντίθημι〉</p></section></article>\n<article id=\"entry-dgp-38931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνθημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2781 na letra σ · nº geral 38931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sinal convencionado ou combinado 2 sinal de reconhecimento; téssera 3 Mil. palavra de ordem; sinal para batalha 4 mensagem codificada 5 senha 6 convenção; tratado; pacto 7 conexão 8 estandarte militar. 〈συντίθημι〉</p></section></article>\n<article id=\"entry-dgp-38932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθηρατής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2782 na letra σ · nº geral 38932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coadjuvante de alguém, dat., na caça de, gen. 〈συνθηράω〉</p></section></article>\n<article id=\"entry-dgp-38933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθηράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2783 na letra σ · nº geral 38933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 caçar junto com alguém, dat. 2 ajudar a prender, a agarrar.</p></section></article>\n<article id=\"entry-dgp-38934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθηρευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2784 na letra σ · nº geral 38934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">συνθηρατής. 〈σύν, θηρεύω〉</p></section></article>\n<article id=\"entry-dgp-38935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνθηρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2785 na letra σ · nº geral 38935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que caça com alguém, dat. ♦ ὁ σύνθηρος 2 companheiro de caçada de alguém, gen. 〈σύν, θήρα〉</p></section></article>\n<article id=\"entry-dgp-38936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθιασώτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2786 na letra σ · nº geral 38936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheiro (de festas, de zombarias) de alguém, gen.</p></section></article>\n<article id=\"entry-dgp-38937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2787 na letra σ · nº geral 38937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quebrar; espatifar; despedaçar junto.</p></section></article>\n<article id=\"entry-dgp-38938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθλίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 2788 na letra σ · nº geral 38938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">apertar junto; comprimir.</p></section></article>\n<article id=\"entry-dgp-38939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθνῄσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 2789 na letra σ · nº geral 38939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">morrer junto com alguém ou algo, dat.</p></section></article>\n<article id=\"entry-dgp-38940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθραύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2790 na letra σ · nº geral 38940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quebrar; esmagar; fazer em pedaços.</p></section></article>\n<article id=\"entry-dgp-38941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθριαμβεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2791 na letra σ · nº geral 38941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">triunfar junto com; compartilhar um triunfo.</p></section></article>\n<article id=\"entry-dgp-38942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθρύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 2792 na letra σ · nº geral 38942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. cortar, partir (o coração); afligir; transtornar.</p></section></article>\n<article id=\"entry-dgp-38943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθρῴσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 2793 na letra σ · nº geral 38943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só. aor.2 συνέθορον) lançar-se junto ou ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνθύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2794 na letra σ · nº geral 38944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">oferecer ou celebrar um sacrifício com alguém, dat. ou μετά e gen.</p></section></article>\n<article id=\"entry-dgp-38945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιδεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 2795 na letra σ · nº geral 38945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de συνοράω.</p></section></article>\n<article id=\"entry-dgp-38946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίει</h1><div class=\"entry-meta\"><span>DGP · ordem 2796 na letra σ · nº geral 38946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. pres. ou 3ª sing. impf. de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιεῖ,</h1><div class=\"entry-meta\"><span>DGP · ordem 2797 na letra σ · nº geral 38947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξυνεῖ 3ª pes. sing. ind. pres. rec. de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιεῖν,</h1><div class=\"entry-meta\"><span>DGP · ordem 2798 na letra σ · nº geral 38948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξυνιεῖν inf. pres. poét. de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιείς,</h1><div class=\"entry-meta\"><span>DGP · ordem 2799 na letra σ · nº geral 38949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξυνιείς, εῖσα, έν part. pres. de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιέμεν,</h1><div class=\"entry-meta\"><span>DGP · ordem 2800 na letra σ · nº geral 38950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξυνιέμεν inf. aor. ép. de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιέναι,</h1><div class=\"entry-meta\"><span>DGP · ordem 2801 na letra σ · nº geral 38951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξυνιέναι inf. pres. de σύνειμι2 ou de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιεράομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2802 na letra σ · nº geral 38952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser parceiro de alguém, dat., nas funções de sacerdote ou sacerdotisa; ser colega de sacerdócio. 〈σύν, ἱερός〉</p></section></article>\n<article id=\"entry-dgp-38953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιερεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2803 na letra σ · nº geral 38953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colega de sacerdócio. 〈σύν, ἱερός〉</p></section></article>\n<article id=\"entry-dgp-38954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2804 na letra σ · nº geral 38954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">honrado por um culto comum. 〈σύν, ἱερός〉</p></section></article>\n<article id=\"entry-dgp-38955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιζάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2805 na letra σ · nº geral 38955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assentar-se; pousar no fundo; afundar 2 fazer cair.</p></section></article>\n<article id=\"entry-dgp-38956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίζησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2806 na letra σ · nº geral 38956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desmoronamento 2 Gram. sinérese; fusão na pronúncia de duas vogais em uma sílaba. 〈συνίζω〉</p></section></article>\n<article id=\"entry-dgp-38957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2807 na letra σ · nº geral 38957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sentar junto 2 cair junto 3 fazer cair.</p></section></article>\n<article id=\"entry-dgp-38958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίημι</h1><div class=\"entry-meta\"><span>DGP · ordem 2808 na letra σ · nº geral 38958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξυνίημι (impf. συνίην e συνίειν, fut. συνήσω, aor. συνῆκα, aor.2 σύνην, perf. συνεῖκα) 1 enviar ou lançar junto ou ao mesmo tempo 2 engajar; impelir alguém, ac., a, inf.: ξυνέηκε μάχεσθαι hom. impeliu ao combate 3 perceber; ouvir algo, gen. ou ac., ou alguém, gen. 4 aprender; conhecer; compreender alguém ou algo, gen. ou ac., or. conj. (ὅτι) ou part.: οὐχὶ ξυνίης; sóf. não entendes? οὐ συνῆκα γεγενημένος luc. não percebi que tinha me tornado, οἱ ξυνιέντες teóg. os inteligentes ♦ méd. συνίεμαι (fut. συνήσομαι, aor. συνείμην) 5 entrar em entendimento, em acordo a respeito de algo, ἀμφί e dat. 6 ouvir; compreender alguém, gen.</p></section></article>\n<article id=\"entry-dgp-38959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνικετεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2809 na letra σ · nº geral 38959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rezar, suplicar junto com.</p></section></article>\n<article id=\"entry-dgp-38960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2810 na letra σ · nº geral 38960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comprimir; contrair. 〈σύν, ἴλλω〉</p></section></article>\n<article id=\"entry-dgp-38961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2811 na letra σ · nº geral 38961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. ép. de σύνειμι2.</p></section></article>\n<article id=\"entry-dgp-38962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιππάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2812 na letra σ · nº geral 38962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">andar a cavalo, cavalgar junto com.</p></section></article>\n<article id=\"entry-dgp-38963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίππαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2813 na letra σ · nº geral 38963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">co-responsável pelo comando da cavalaria.</p></section></article>\n<article id=\"entry-dgp-38964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνισαν</h1><div class=\"entry-meta\"><span>DGP · ordem 2814 na letra σ · nº geral 38964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. 1 = συνῃέσαν, 3ª pl. impf. de σύνειμι2 2 = συνῄδεσαν, 3ª pl. m.-q.-perf. de σύνοιδα.</p></section></article>\n<article id=\"entry-dgp-38965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίστημι</h1><div class=\"entry-meta\"><span>DGP · ordem 2815 na letra σ · nº geral 38965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνίστημι (pres., impf. συνίστην, fut. συστήσω, aor.1 συνέστησα, perf. συνέστακα) ativa 1 pôr junto; combinar; reunir uma coisa ou pessoa, ac., com outra, dat. ou πρός e ac. 2 pôr uma pessoa, ac., em contato com outra, dat.; apresentar 3 entregar aos cuidados de; confiar uma pessoa, ac., a outra 4 tornar compacto, sólido; dar consistência a, ac. 5 constituir; formar algo, ac., a partir de, ἐκ e gen.; instituir; fundar 6 estabelecer; decidir; fixar 7 reunir em um todo pela junção de suas partes; compor; criar; produzir 8 juntar; contrair; dobrar, enrugar 9 argumentar; provar; mostrar algo, ac., ou que, or. conj. (ὅτι) ou inf. ativa (aor.2 συνέστην, perf. συνέστηκα, m.-q.-perf. συνειστήκειν) e média 10 (pessoa) compartilhar algo, ac., com alguém, dat. 11 manter-se, dispor-se junto; agrupar-se 12 alinhar-se junto a; aliar-se a alguém, dat. ou μετά e gen. ou πρός e ac., contra alguém, ἐπί e ac.; coligar-se 13 manter-se firme; resistir 14 enfrentar; combater; debater-se com, dat. 15 intr. (combate) travar-se; produzir-se 16 intr. unir-se; organizar-se 17 intr. formar-se pela reunião de muitas partes; tomar forma; tomar corpo; constituir-se de, ἐκ e gen.; perf. estar formado, constituído 18 intr. ser ou tornar-se sólido ou compacto; ganhar consistência; ser consistente, firme, sólido; endurecer-se 19 intr. manter-se; ser durável 20 intr. contrair-se; estreitar-se; (semblante) contrair-se; entristecer-se 21 intr. (líquido) coalhar; coagular-se 1 τοὺς ἐκ τῆς τροπῆς σκεδασθέντας σ. d.h. reunir os fugitivos dispersos, σ. τοὺς Ἀρκάδας ἐπὶ τῇ Σπάρτη her. agrupar os arcádios contra Esparta, τὴν Ἄλυος ποταμοῦ ἄνω Ἀσίην πᾶσαν συστήσας ἑωυτῷ her. reunir em torno de si, i.e., unificar sob sua autoridade toda a Ásia acima do rio Hális, τὰς χορδὰς ἀλλήλαις σ. plat. afinar as cordas umas com as outras, σ. τὰς πόλεις πρὸς ἀλλήλας xen. coligar as cidades umas com as outras 2 συστήσω δέ σοι ἐγὼ καὶ Ἀσπασίαν xen. eu te apresentarei também Aspásia 3 συνέστησεν ὁ ἀρχιδεσμώτης τῷ Ἰωσηφ αὐτούς sept. o chefe da guarda confiou-os a José 4 τὰ δὲ βόρεια συνίστησι καὶ σῴζει xen. os ventos do norte tornam consistentes e preservam [as pegadas], σ. τὰς τιμὰς τοῦ σίτου dem. aumentar o preço do trigo 5 σ. τὴν ὀλιγαρχίαν tuc. constituir uma oligarquia, ἐκ χρηστῶν καὶ κακῶν ἀνθρώπων σ. πόλιν plat. formar de homens bons e de homens maus uma cidade, ὁ ἡμέτερος πρόγονος Ἀσκληπιός συνέστησεν τὴν ἡμετέραν τέχνην plat. o nosso ancestral Asclépio fundou a nossa arte, τὸ δ᾽ ἐν ταῖς γυναιξὶν συστήσαντες ἔμψυχον plat. tendo [os deuses] incutido nas mulheres o [desejo sexual] vital 6 ἥκω σπουδῇ ὡς συστήσων ἐπὶ τῷ Μάγῳ θάνατον her. aqui estou pressuroso para decidir a morte do mago 7 σ. μύθους artt. compor fábulas, σ. πόλεμον dem. provocar uma guerra 8 σ. τὸ πρόσωπον plut. franzir o rosto 9 σ. θεοῦ δικαιοσύνην n.t. mostrar a justiça divina, ἐπειρᾶτο συνιστάνειν ὅτι τῶν μὲν ἐν ταῖς προγεγενημέναις μάχαις ἐλαττωμάτων οὐχ ἓν οὐδὲ δεύτερον, καὶ πλείω δ᾽ ἂν εὕροι τις αἴτια pol. empenhava-se em mostrar que dos fracassos nas batalhas anteriores era possível apontar não uma nem duas, mas muitas razões 10 λέχος Ἡρακλεῖ ξυστᾶσα sóf. Tr. compartilhando o leito com Héracles 11 οἱ μεγάλοι ἀνδριάντες οἱ περὶ τὸν τρίποδα συνεστεῶτες ἔμπροσθε τοῦ νηοῦ τοῦ ἐν Δελφοῖσι her. as grandes estátuas agrupadas ao redor da trípode diante do templo de Delfos, ἁθρόοι συστάντες xen. permanecendo reunidos em massa 12 εἰ ξυστῶσιν αἱ πόλεις φοβηθεῖσαι tuc. se as cidades apavoradas se coligassem, οὐ ξυνειστήκεσαν πρὸς τὰς μεγίστας πόλεις ὑπήκοοι tuc. cidades submissas não haviam se coligado com as mais importantes, τὸ ἄλλο Ἑλληνικὸν ὁρῶν ξυνιστάμενον πρὸς ἑκατέρους tuc. vendo o restante do povo grego alinhando-se a um e outro lado, οἱ ξυνιστάμενοι ar. os conspiradores 13 χρόνον τε δὴ ἐπὶ πολλὸν συνεστάναι μαχομένους her. [conta-se que] durante longo tempo mantiveram-se firme no combate 14 οὐ δυναμένους οὔτε ἑλεῖν οὔτε παραμένειν λιμῷ συνεστεῶτας her. não podendo eles nem tomar [a cidade] nem manter o cerco, βουλόμενοι τοὺς Ἀθηναίους ἔχειν πόνους συνεστεῶτας Βοιωτοῖσι her. desejosos de que os atenienses sofressem ao enfrentar os beócios, τὸ δὲ ἄλλο καρτερᾷ μάχῃ καὶ ὠθισμῷ ἀσπίδων ξυνειστήκει tuc. o restante [do exército] envolveu-se em encarniçada batalha e entrechoque de escudos, γνῶμαι μὲν αὗται συνέστασαν her. essas opiniões entraram em conflito 15 συνήνεικε ὥστε τῆς μάχης συνεστεώσης τὴν ἡμέρην ἐξαπίνης νύκτα γενέσθαι her. ocorreu que, enquanto se travava o combate, o dia subitamente se fez noite, κατὰ γῆν δὲ πόλεμος, ὅθεν τις καὶ δύναμις παρεγένετο, οὐδεὶς ξυνέστη tuc. em terra, porém, não se travou nenhuma guerra de onde se originasse algum poder 16 καὶ ξύλλογοι ἐγίγνοντο καὶ κύκλοι ξυνίσταντο xen. formavam-se ajuntamentos e grupos se organizavam 17 ἡ μὲν πόλις ἐκ πλειόνων ἢ μυρίων οἰκιῶν συνέστηκε xen. a cidade é constituída de mais de dez mil casas, ξυνεστὼς στρατός eur. exército reunido (pronto para partir), συνιστάμενον καὶ φυόμενον κακόν dem. mal que se forma e se desenvolve, πόλιν οὕτω συστᾶσαν plat. uma cidade assim constituída, συνεστῶτες εὖ μῦθοι artt. fábulas bem compostas 18 σώματα συνεστηκότα xen. corpos compactos, συνεστηκυῖα χιών pol. neve solidificada 19 τοῦτο συνεστήκεε μέχρι οὖ her. esta situação se prolongou até o momento em que, συνεστηκὸς στράτευμα dem. exército permanente 20 κοιλίη συνίσταται hipócr. o ventre se constipa, βάδην δὲ καὶ συνεστῶτι τῷ προσώπῳ μετὰ πολλῆς σιωπῆς προσιόντος plut. avançando passo a passo em silêncio e com o rosto contraído, τοῦ σκυθρωποῦ καὶ ξυνεστῶτος φρενῶν eur. de alma sombria e oprimida 21 συνίσταται τὸ αἶμα artt. o sangue coagula.</p></section></article>\n<article id=\"entry-dgp-38966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίστωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 2816 na letra σ · nº geral 38966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 testemunha de algo, gen. ou ac. 2 cônscio; ciente de, gen. 〈σύν, ἵστωρ〉</p></section></article>\n<article id=\"entry-dgp-38967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνισχναίνω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2817 na letra σ · nº geral 38967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνισχναίνω 1 secar 2 minguar; diminuir 3 mitigar ♦ pas. 4 secar-se totalmente.</p></section></article>\n<article id=\"entry-dgp-38968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνισχυρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2818 na letra σ · nº geral 38968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. át. συνισχυριῶ) fortificar com; ajudar a fortalecer.</p></section></article>\n<article id=\"entry-dgp-38969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνίω</h1><div class=\"entry-meta\"><span>DGP · ordem 2819 na letra σ · nº geral 38969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. pres. de σύνειμι2.</p></section></article>\n<article id=\"entry-dgp-38970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνιών, οῦσα, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2820 na letra σ · nº geral 38970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. de σύνειμι2.</p></section></article>\n<article id=\"entry-dgp-38971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνναίω</h1><div class=\"entry-meta\"><span>DGP · ordem 2821 na letra σ · nº geral 38971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só. pres.) habitar com; viver com; conviver com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνναος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2822 na letra σ · nº geral 38972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">venerado no mesmo templo com, gen. ou dat. 〈σύν, ναός〉</p></section></article>\n<article id=\"entry-dgp-38973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 2823 na letra σ · nº geral 38973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. part. συννάξαντες) ser confinado junto ou ser prensado junto.</p></section></article>\n<article id=\"entry-dgp-38974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνναυβάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2824 na letra σ · nº geral 38974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheiro de travessia ou membro da equipagem de um navio.</p></section></article>\n<article id=\"entry-dgp-38975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνναύκληρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2825 na letra σ · nº geral 38975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">co-piloto de navio.</p></section></article>\n<article id=\"entry-dgp-38976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνναυμαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2826 na letra σ · nº geral 38976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ajudar alguém, dat., a empreender uma batalha naval.</p></section></article>\n<article id=\"entry-dgp-38977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνναυστολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2827 na letra σ · nº geral 38977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. pl. συννεναυστοληκότες) navegar com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνναύτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2828 na letra σ · nº geral 38978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheiro de navegação.</p></section></article>\n<article id=\"entry-dgp-38979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννέμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2829 na letra σ · nº geral 38979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relação com algo, πρός e ac. 〈συννέμω〉</p></section></article>\n<article id=\"entry-dgp-38980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 2830 na letra σ · nº geral 38980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 partilhar ou associar junto 2 fazer pastar junto ♦ méd. 3 pastorear junto ♦ pas. 4 ser associado.</p></section></article>\n<article id=\"entry-dgp-38981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννενέαται</h1><div class=\"entry-meta\"><span>DGP · ordem 2831 na letra σ · nº geral 38981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. jôn. perf. pas. de συννέω3.</p></section></article>\n<article id=\"entry-dgp-38982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύννευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2832 na letra σ · nº geral 38982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">disposição de coisas que convergem uma para outra. 〈συννέυω〉</p></section></article>\n<article id=\"entry-dgp-38983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2833 na letra σ · nº geral 38983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acenar junto ou um para o outro: σ. τὰς ὀφρῦς κάτω luc. contrair as sobrancelhas 2 inclinar-se junto ou um para o outro; convergir para, πρός e ac. 3 fazer um sinal de assentimento; concordar; prometer.</p></section></article>\n<article id=\"entry-dgp-38984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννέφελος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2834 na letra σ · nº geral 38984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">συννεφής. 〈σύν, νεφέλη〉</p></section></article>\n<article id=\"entry-dgp-38985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννεφέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2835 na letra σ · nº geral 38985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυννεφέω-ῶ 1 reunir nuvens 2 cobrir-se de nuvens; tornar-se sombrio; impes. συννεφεῖ artt. o tempo está encoberto 3 ter um ar sombrio; ser infeliz. 〈συννεφής〉</p></section></article>\n<article id=\"entry-dgp-38986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2836 na letra σ · nº geral 38986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coberto de nuvens; nublado 2 triste; taciturno; sombrio (pessoa). 〈σύν, νέφος〉</p></section></article>\n<article id=\"entry-dgp-38987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννέω1</h1><div class=\"entry-meta\"><span>DGP · ordem 2837 na letra σ · nº geral 38987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nadar com, dat.</p></section></article>\n<article id=\"entry-dgp-38988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννέω2</h1><div class=\"entry-meta\"><span>DGP · ordem 2838 na letra σ · nº geral 38988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fiar ou tecer junto.</p></section></article>\n<article id=\"entry-dgp-38989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννέω3,</h1><div class=\"entry-meta\"><span>DGP · ordem 2839 na letra σ · nº geral 38989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυννέω (fut. συννήσω, aor. συνένησα; perf. pas. συννένημαι) 1 amontoar, acumular: σ. πυρήν her. construir uma pira com madeira amontoada, τῶν νεκρῶν ἐπ᾽ ἀλλήλοις ξυννενημένων tuc. os cadáveres estando empilhados uns sobre os outros 2 fazer amontoar: σ. ἀκόντια καὶ δοράτια her. empilhar dardos e lanças.</p></section></article>\n<article id=\"entry-dgp-38990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννήχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2840 na letra σ · nº geral 38990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nadar com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννικάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2841 na letra σ · nº geral 38991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ajudar alguém, dat., a vencer.</p></section></article>\n<article id=\"entry-dgp-38992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννοέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2842 na letra σ · nº geral 38992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυννοέω-ῶ at. e méd. 1 pensar; meditar; refletir sobre algo, ac. 2 compreender algo, or. conj. (ὅτι, ὡς) ou part.</p></section></article>\n<article id=\"entry-dgp-38993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύννοια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2843 na letra σ · nº geral 38993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 reflexão; meditação 2 preocupação; inquietação 3 consciência; remorso. 〈σύννοος〉</p></section></article>\n<article id=\"entry-dgp-38994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννομέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2844 na letra σ · nº geral 38994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pastar com. 〈σύννομος〉</p></section></article>\n<article id=\"entry-dgp-38995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύννομος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2845 na letra σ · nº geral 38995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξύννομος, ος, ον 1 que pasta junto com, dat. 2 que vive junto ou em grupo 3 associado a; ligado a; vizinho de, gen.: θαλάσσης σύννομοι πέτραι eur. rochas vizinhas do mar, rochas Cirônides 4 habitual a, dat. 5 que partilha algo, gen., com, dat.: λέκτρων ξύννομος ésql. que partilha o leito ♦ ὁ, ἡ σύννομος 6 companheiro; esposo; esposa. 〈συννέμω〉</p></section></article>\n<article id=\"entry-dgp-38996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύννοος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 2846 na letra σ · nº geral 38996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 imerso em pensamentos; pensativo; meditativo 2 circunspecto; preocupado; sério 3 prudente.</p></section></article>\n<article id=\"entry-dgp-38997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννοσέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2847 na letra σ · nº geral 38997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar doente junto com alguém, dat. 2 ser acometido do mesmo mal que alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύννους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 2848 na letra σ · nº geral 38998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de σύννοος.</p></section></article>\n<article id=\"entry-dgp-38999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συννυμφοκόμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2849 na letra σ · nº geral 38999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ajuda a enfeitar, a adornar a noiva.</p></section></article>\n<article id=\"entry-dgp-39000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνοδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2850 na letra σ · nº geral 39000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer uma viagem junto com alguém, dat. 2 Astron. (sol, lua, terra) estar em conjunção 3 bíbl. ser companheiro de 4 Gram. acompanhar; vir junto com algo, dat.</p></section></article>\n";
